1	package server
2	
3	import (
4		"math"
5		"net/http"
6		"sort"
7		"sync"
8	)
9	
10	// deviceInput is one member of a create-pool request.
11	type deviceInput struct {
12		ID            string `json:"id"`
13		CapacityBytes int64  `json:"capacityBytes"`
14		FaultDomain   string `json:"faultDomain"`
15	}
16	
17	type createPoolInput struct {
18		ID      string        `json:"id"`
19		Devices []deviceInput `json:"devices"`
20	}
21	
22	type reservationInput struct {
23		RequestID string `json:"requestId"`
24		Bytes     int64  `json:"bytes"`
25	}
26	
27	// deviceView is the public representation of a pool device.
28	type deviceView struct {
29		ID            string `json:"id"`
30		CapacityBytes int64  `json:"capacityBytes"`
31		FaultDomain   string `json:"faultDomain"`
32	}
33	
34	// poolView is the public representation of a storage pool.
35	type poolView struct {
36		ID               string       `json:"id"`
37		Devices          []deviceView `json:"devices"`
38		RawCapacityBytes int64        `json:"rawCapacityBytes"`
39		AllocatedBytes   int64        `json:"allocatedBytes"`
40		AvailableBytes   int64        `json:"availableBytes"`
41	}
42	
43	// reservationView is the result of a successful reservation request.
44	type reservationView struct {
45		PoolID    string `json:"poolId"`
46		RequestID string `json:"requestId"`
47		Bytes     int64  `json:"bytes"`
48	}
49	
50	type reservation struct {
51		requestID string
52		bytes     int64
53	}
54	
55	type pool struct {
56		id            string
57		devices       []deviceInput
58		rawCapacity   int64
59		reservations  map[string]reservation
60		volumeBytes   int64 // total sizeBytes of volumes in this pool
61		snapshotBytes int64 // total sizeBytes of snapshots held in this pool
62		objectBytes   int64 // total sizeBytes of objects in buckets of this pool
63	}
64	
65	// volume is a capacity allocation inside a pool with an optional exclusive
66	// node binding. generation is bumped on every binding state change.
67	// cloneSource records the snapshot a volume was cloned from ("" for a volume
68	// created directly) so clone retries can be told apart from foreign ids.
69	type volume struct {
70		id          string
71		poolID      string
72		sizeBytes   int64
73		generation  int64
74		binding     string // "" when unbound
75		cloneSource string // snapshot id when produced via a clone
76	}
77	
78	func (p *pool) allocated() int64 {
79		var total int64 = p.volumeBytes + p.snapshotBytes + p.objectBytes
80		for _, r := range p.reservations {
81			total += r.bytes
82		}
83		return total
84	}
85	
86	func (p *pool) view() poolView {
87		devices := make([]deviceView, len(p.devices))
88		for i, d := range p.devices {
89			devices[i] = deviceView{ID: d.ID, CapacityBytes: d.CapacityBytes, FaultDomain: d.FaultDomain}
90		}
91		allocated := p.allocated()
92		return poolView{
93			ID:               p.id,
94			Devices:          devices,
95			RawCapacityBytes: p.rawCapacity,
96			AllocatedBytes:   allocated,
97			AvailableBytes:   p.rawCapacity - allocated,
98		}
99	}
100	
101	// store is the in-memory state of the service. It is wiped on restart.
102	type store struct {
103		mu          sync.RWMutex
104		pools       map[string]*pool
105		volumes     map[string]*volume
106		snapshots   map[string]*snapshot
107		buckets     map[string]*bucket
108		deviceOwner map[string]string
109	}
110	
111	func newStore() *store {
112		return &store{
113			pools:       make(map[string]*pool),
114			volumes:     make(map[string]*volume),
115			snapshots:   make(map[string]*snapshot),
116			buckets:     make(map[string]*bucket),
117			deviceOwner: make(map[string]string),
118		}
119	}
120	
121	func validID(id string) bool {
122		return idPattern.MatchString(id)
123	}
124	
125	func (s *store) listPools(w http.ResponseWriter) {
126		s.mu.RLock()
127		ids := make([]string, 0, len(s.pools))
128		for id := range s.pools {
129			ids = append(ids, id)
130		}
131		sort.Strings(ids)
132		items := make([]poolView, 0, len(ids))
133		for _, id := range ids {
134			items = append(items, s.pools[id].view())
135		}
136		s.mu.RUnlock()
137		writeJSON(w, http.StatusOK, map[string]any{"items": items})
138	}
139	
140	func (s *store) getPool(w http.ResponseWriter, id string) {
141		if !validID(id) {
142			writeError(w, http.StatusBadRequest, "invalid_request")
143			return
144		}
145		s.mu.RLock()
146		p, ok := s.pools[id]
147		var v poolView
148		if ok {
149			v = p.view()
150		}
151		s.mu.RUnlock()
152		if !ok {
153			writeError(w, http.StatusNotFound, "pool_not_found")
154			return
155		}
156		writeJSON(w, http.StatusOK, v)
157	}
158	
159	func (s *store) createPool(w http.ResponseWriter, r *http.Request) {
160		var in createPoolInput
161		if !decodeRequest(r, &in) {
162			writeError(w, http.StatusBadRequest, "invalid_request")
163			return
164		}
165		// Validate the whole payload before touching any state so a failure
166		// never leaves a partial pool behind.
167		if !validID(in.ID) || len(in.Devices) == 0 {
168			writeError(w, http.StatusBadRequest, "invalid_request")
169			return
170		}
171		seen := make(map[string]bool, len(in.Devices))
172		var rawCapacity int64
173		for _, d := range in.Devices {
174			if !validID(d.ID) || d.CapacityBytes <= 0 || d.FaultDomain == "" || seen[d.ID] {
175				writeError(w, http.StatusBadRequest, "invalid_request")
176				return
177			}
178			if rawCapacity > math.MaxInt64-d.CapacityBytes {
179				writeError(w, http.StatusBadRequest, "invalid_request")
180				return
181			}
182			seen[d.ID] = true
183			rawCapacity += d.CapacityBytes
184		}
185	
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		if _, ok := s.pools[in.ID]; ok {
189			writeError(w, http.StatusConflict, "pool_exists")
190			return
191		}
192		for _, d := range in.Devices {
193			if _, busy := s.deviceOwner[d.ID]; busy {
194				writeError(w, http.StatusConflict, "device_in_use")
195				return
196			}
197		}
198	
199		devices := append([]deviceInput(nil), in.Devices...)
200		p := &pool{
201			id:           in.ID,
202			devices:      devices,
203			rawCapacity:  rawCapacity,
204			reservations: make(map[string]reservation),
205		}
206		s.pools[in.ID] = p
207		for _, d := range devices {
208			s.deviceOwner[d.ID] = in.ID
209		}
210		writeJSON(w, http.StatusCreated, p.view())
211	}
212	
213	func (s *store) deletePool(w http.ResponseWriter, id string) {
214		if !validID(id) {
215			writeError(w, http.StatusBadRequest, "invalid_request")
216			return
217		}
218		s.mu.Lock()
219		defer s.mu.Unlock()
220		p, ok := s.pools[id]
221		if !ok {
222			writeError(w, http.StatusNotFound, "pool_not_found")
223			return
224		}
225		if len(p.reservations) > 0 || p.volumeBytes > 0 || p.snapshotBytes > 0 || p.objectBytes > 0 {
226			writeError(w, http.StatusConflict, "pool_not_empty")
227			return
228		}
229		// An empty bucket still blocks pool deletion even though it charges no
230		// bytes.
231		for _, b := range s.buckets {
232			if b.poolID == id {
233				writeError(w, http.StatusConflict, "pool_not_empty")
234				return
235			}
236		}
237		for _, d := range p.devices {
238			delete(s.deviceOwner, d.ID)
239		}
240		delete(s.pools, id)
241		w.WriteHeader(http.StatusNoContent)
242	}
243	
244	func (s *store) createReservation(w http.ResponseWriter, r *http.Request, poolID string) {
245		var in reservationInput
246		if !decodeRequest(r, &in) {
247			writeError(w, http.StatusBadRequest, "invalid_request")
248			return
249		}
250		if !validID(poolID) || !validID(in.RequestID) || in.Bytes <= 0 {
251			writeError(w, http.StatusBadRequest, "invalid_request")
252			return
253		}
254	
255		s.mu.Lock()
256		defer s.mu.Unlock()
257		p, ok := s.pools[poolID]
258		if !ok {
259			writeError(w, http.StatusNotFound, "pool_not_found")
260			return
261		}
262		if existing, dup := p.reservations[in.RequestID]; dup {
263			if existing.bytes != in.Bytes {
264				writeError(w, http.StatusConflict, "idempotency_conflict")
265				return
266			}
267			writeJSON(w, http.StatusOK, reservationView{PoolID: poolID, RequestID: existing.requestID, Bytes: existing.bytes})
268			return
269		}
270		allocated := p.allocated()
271		if allocated > p.rawCapacity-in.Bytes {
272			writeError(w, http.StatusConflict, "insufficient_capacity")
273			return
274		}
275		p.reservations[in.RequestID] = reservation{requestID: in.RequestID, bytes: in.Bytes}
276		writeJSON(w, http.StatusCreated, reservationView{PoolID: poolID, RequestID: in.RequestID, Bytes: in.Bytes})
277	}
278	
279	func (s *store) deleteReservation(w http.ResponseWriter, poolID, requestID string) {
280		if !validID(poolID) || !validID(requestID) {
281			writeError(w, http.StatusBadRequest, "invalid_request")
282			return
283		}
284		s.mu.Lock()
285		defer s.mu.Unlock()
286		p, ok := s.pools[poolID]
287		if !ok {
288			writeError(w, http.StatusNotFound, "pool_not_found")
289			return
290		}
291		// Deleting an unknown or already-deleted reservation is a success.
292		delete(p.reservations, requestID)
293		w.WriteHeader(http.StatusNoContent)
294	}
