	if !ok {
		writeError(w, http.StatusNotFound, "bucket_not_found")
		return
	}
	// Deleting an unknown or already-deleted object is a success.
	if o, exists := b.objects[key]; exists {
		s.pools[b.poolID].objectBytes -= o.sizeBytes
